INSERT INTO menu_nodes (id, parent_id, slug, title, content, sort_order) VALUES
(2, 1, 'info', 'ℹ️ Информация', 'Здесь Вы можете узнать различную информацию об университете. Выберите интересующую Вас категорию:', 0),
(3, 1, 'about', '📌 О проекте', 'Доступный ПГУПС — проект, разрабатываемый в рамках студенческого общества факультета «Автоматизация и Интеллектуальные Технологии».', 1);
