(64, 41, 'sd5', 'Общежитие №5', E'🏢 Общежитие №5\n\n👤 Заведующий: Дуркина Светлана Александровна\n✉️ hostel5@pgups.ru\n📞 +7(812)233-54-30, +7(812)232-35-76, +7(812)233-11-74\n📍 ул. Малая Посадская, д. 22-24\n🔗 https://vk.com/dormitory_5', 4),
(65, 41, 'sd5k3', 'Общежитие №5 к.3', E'🏢 Общежитие №5 к.3\n\n👤 Заведующий: Савицкий Павел Павлович\n✉️ hostel5k3@pgups.ru\n📞 +7(812)233-89-25, +7(812)233-27-03\n📍 ул. Малая Посадская, д. 22-24\n🔗 https://vk.com/obschaga5k3pgups', 5),
(66, 41, 'sd6', 'Общежитие №6', E'🏢 Общежитие №6\n\n👤 Заведующий: Кучук Дмитрий Иосифович\n📞 +7(812)714-82-65\n✉️ hostel6@pgups.ru\n📍 ул. Перевозная, д.2\n🔗 https://vk.com/hostelnumbersix', 6),
(67, 41, 'sd7a', 'Общежитие №7а', E'🏢 Общежитие №7а\n\n👤 Заведующий: Савицкий Павел Павлович\n✉️ hostel7a@pgups.ru\n📞 +7(812)232-14-86, +7(812)232-40-68, +7(812)232-76-84\n📍 ул. Малая Посадская, д. 22-24\n🔗 https://vk.com/club217049829', 7),
(68, 41, 'sd8', 'Общежитие №8', E'🏢 Общежитие №8\n\n👤 Заведующий: Кожевников Александр Анатольевич\n✉️ hostel8@pgups.ru\n📞 +7(812)465-90-50, +7(812)476-17-33, +7(812)465-99-85, +7(812)465-94-86\n📍 г. Пушкин, ул. Оранжерейная, д.73\n🔗 https://vk.com/hostel_8_pgups', 8);
INSERT INTO menu_nodes (id, parent_id, slug, title, content, sort_order) VALUES
(70, 42, 'canteens', '🍽 Столовые', E'🍽 Столовые в университете:\n\n• ауд. 7-205\n• ауд. 7-206\n• ауд. 1-219\n• ауд. 3-208', 0),
(71, 42, 'libraries', '📚 Библиотеки', E'📚 Библиотеки университета:\n\n• Основная библиотека — ауд. 3-207\n• Научно-техническая — ауд. 6-211\n• Общественно-политической литературы — ауд. 1-309\n• Художественной литературы — ауд. 1-314\n\n⚠️ Читательский билет оформляется в первый месяц обучения в ауд. 3-207.', 1),
